sect3.example:
    Parametri passati per riferimento tipizzati


<?php
function array_baz(array &$param)
{
    $param = 1;
}
$var = [];
array_baz($var);
var_dump($var);
array_baz($var);
?>


    &example.outputs.similar;


int(1)

Fatal error: Uncaught TypeError: array_baz(): Argument #1 ($param) must be of type array, int given, called in - on line 9 and defined in -:2
Stack trace:
#0 -(9): array_baz(1)
#1 {main}
  thrown in - on line 2

note.example:
      Vecchio modo per rendere gli argomenti nullable


<?php
class C {}

function f(C $c = null) {
    var_dump($c);
}

f(new C);
f(null);
?>


      &example.outputs;


object(C)#1 (0) {
}
NULL

sect3.para:
    Ad esempio, se A e B sono alias di
    classe, A|B rimane un tipo union legale, anche
    se potrebbe essere ridotto a A o
    B.
    Allo stesso modo, se la classe B extends A {}, anche A|B
    è un tipo union legale, anche se potrebbe essere ridotto solo a
    A.




<?php
function foo(): int|INT {} // Non consentito
function foo(): bool|false {} // Non consentito
function foo(): int&Traversable {} // Non consentito
function foo(): self&Traversable {} // Non consentito

use A as B;
function foo(): A|B {} // Non consentito ("use" fa parte della risoluzione dei nomi)
function foo(): A&B {} // Non consentito ("use" fa parte della risoluzione dei nomi)

class_alias('X', 'Y');
function foo(): X|Y {} // Consentito (la ridondanza è nota solo in fase di esecuzione)
function foo(): X&Y {} // Consentito (la ridondanza è nota solo in fase di esecuzione)
?>

sect1.sect2:
  &reftitle.examples;

   Dichiarazione di base del tipo classe


<?php
class C {}
class D extends C {}

// Questa non estende C.
class E {}

function f(C $c) {
    echo get_class($c)."\n";
}

f(new C);
f(new D);
f(new E);
?>


   &example.outputs.8;


C
D

Fatal error: Uncaught TypeError: f(): Argument #1 ($c) must be of type C, E given, called in /in/gLonb on line 14 and defined in /in/gLonb:8
Stack trace:
#0 -(14): f(Object(E))
#1 {main}
  thrown in - on line 8





   Dichiarazione di base del tipo interfaccia


<?php
interface I { public function f(); }
class C implements I { public function f() {} }

// Questa non implementa I.
class E {}

function f(I $i) {
    echo get_class($i)."\n";
}

f(new C);
f(new E);
?>


   &example.outputs.8;


C

Fatal error: Uncaught TypeError: f(): Argument #1 ($i) must be of type I, E given, called in - on line 13 and defined in -:8
Stack trace:
#0 -(13): f(Object(E))
#1 {main}
  thrown in - on line 8





   Dichiarazione di base del tipo restituito


<?php
function sum($a, $b): float {
    return $a + $b;
}

// Notare che verrà restituito un float.
var_dump(sum(1, 2));
?>


   &example.outputs;


float(3)





   Restituzione di un oggetto


<?php
class C {}

function getC(): C {
    return new C;
}

var_dump(getC());
?>


   &example.outputs;


object(C)#1 (0) {
}





   Dichiarazione del tipo di argomento nullable


<?php
class C {}

function f(?C $c) {
    var_dump($c);
}

f(new C);
f(null);
?>


   &example.outputs;


object(C)#1 (0) {
}
NULL





   Dichiarazione del tipo restituito nullable


<?php
function get_item(): ?string {
    if (isset($_GET['item'])) {
        return $_GET['item'];
    } else {
        return null;
    }
}
?>





   Dichiarazione del tipo di una proprietà di classe


<?php
class User {
    public static string $foo = 'foo';

    public int $id;
    public string $username;

    public function __construct(int $id, string $username) {
        $this->id = $id;
        $this->username = $username;
    }
}
?>

sect2.example:
   Tipizzazione strict per i valori degli argomenti


<?php
declare(strict_types=1);

function sum(int $a, int $b) {
    return $a + $b;
}

var_dump(sum(1, 2));
var_dump(sum(1.5, 2.5));
?>


   &example.outputs.8;


int(3)

Fatal error: Uncaught TypeError: sum(): Argument #1 ($a) must be of type int, float given, called in - on line 9 and defined in -:4
Stack trace:
#0 -(9): sum(1.5, 2.5)
#1 {main}
  thrown in - on line 4

   Tipizzazione coercitiva per i valori degli argomenti


<?php
function sum(int $a, int $b) {
    return $a + $b;
}

var_dump(sum(1, 2));

// Questi verranno convertiti in interi: si noti l'output qui sotto!
var_dump(sum(1.5, 2.5));
?>


   &example.outputs;


int(3)
int(3)

   Tipizzazione strict per i valori di ritorno


<?php
declare(strict_types=1);

function sum($a, $b): int {
    return $a + $b;
}

var_dump(sum(1, 2));
var_dump(sum(1, 2.5));
?>


   &example.outputs;


int(3)

Fatal error: Uncaught TypeError: sum(): Return value must be of type int, float returned in -:5
Stack trace:
#0 -(9): sum(1, 2.5)
#1 {main}
  thrown in - on line 5
